    UMethod[] methods = node.getMethods();
    boolean hasConstructor = false;
    for (UMethod method : methods) {
        if (method.isConstructor()) {
            hasConstructor = true;
            if (isMainThreadConstructor(method, new HashSet<UMethod>())) {
                return true;
            }
        }
    }
    if (!hasConstructor) {
        return true;
    }
    return false;
}
```
